srcDoc.css:
body {
  margin: 0;
  background: #eef1f5;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 18px;
  box-sizing: border-box;
}

.print-button {
  display: block;
  margin: 0 auto 14px;
  width: 220px;
  height: 42px;
  border: 0;
  border-radius: 7px;
  background: #101828;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.manifest {
  width: 210mm;
  min-height: 297mm;
  margin: 0 auto;
  background: white;
  box-sizing: border-box;
  padding: 14mm;
  box-shadow: 0 18px 50px rgba(15, 23, 42, 0.16);
}

.top-line {
  height: 7px;
  margin: -14mm -14mm 14mm;
  background: linear-gradient(90deg, #101828, #2563eb, #0f766e);
}

.header {
  display: flex;
  justify-content: space-between;
  gap: 28px;
  border-bottom: 1px solid #d0d5dd;
  padding-bottom: 18px;
}

.brand {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.logo {
  width: 92px;
  max-height: 76px;
  object-fit: contain;
}

.logo-fallback {
  width: 84px;
  height: 68px;
  background: #101828;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: 900;
}

.company-name {
  font-size: 25px;
  line-height: 1.1;
  font-weight: 900;
}

.company-meta {
  margin-top: 8px;
  color: #667085;
  font-size: 12px;
  line-height: 1.45;
}

.title-box {
  text-align: right;
  min-width: 260px;
}

.badge {
  display: inline-block;
  padding: 6px 10px;
  background: #f2f4f7;
  color: #2563eb;
  border: 1px solid #d0d5dd;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

.title-box h1 {
  margin: 10px 0 5px;
  font-size: 32px;
  letter-spacing: 0;
}

.doc-no {
  font-size: 18px;
  font-weight: 900;
}

.status {
  display: inline-block;
  margin-top: 8px;
  padding: 5px 9px;
  border: 1px solid #d0d5dd;
  font-size: 12px;
  font-weight: 800;
}

.manifest-barcode-section {
  margin: 16px 0 18px;
  padding: 12px 14px;
  border: 1px solid #d0d5dd;
  background: white;
}

.manifest-barcode-title {
  color: #667085;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  margin-bottom: 7px;
}

.manifest-barcode {
  width: 100%;
}

.manifest-barcode svg {
  display: block;
  width: 100%;
  height: 94px;
}

.info-strip {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  margin: 18px 0;
}

.info-box,
.party-box,
.note-box,
.summary-box {
  border: 1px solid #d0d5dd;
  padding: 11px;
}

.label {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  margin-bottom: 5px;
  font-weight: 700;
}

.value {
  font-size: 13px;
  font-weight: 800;
}

.party-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-bottom: 18px;
}

.party-box h2 {
  margin: 0 0 8px;
  font-size: 17px;
}

.party-box p {
  margin: 0;
  color: #667085;
  font-size: 12px;
  line-height: 1.5;
}

.items-wrap {
  border: 1px solid #d0d5dd;
}

.items-head {
  display: flex;
  justify-content: space-between;
  background: #101828;
  color: white;
  padding: 11px 12px;
}

.items-head h2 {
  margin: 0;
  font-size: 15px;
}

.items-head span {
  color: #d0d5dd;
  font-size: 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  background: #f2f4f7;
  color: #344054;
  font-size: 11px;
  text-align: left;
  padding: 9px 8px;
  border-bottom: 1px solid #d0d5dd;
}

td {
  padding: 9px 8px;
  font-size: 12px;
  vertical-align: top;
  border-bottom: 1px solid #eaecf0;
}

tbody tr:nth-child(even) {
  background: #fbfcfd;
}

.product-code {
  font-weight: 900;
}

.product-name {
  margin-top: 2px;
  color: #667085;
  font-size: 11px;
}

small {
  display: block;
  margin-top: 2px;
  color: #667085;
  font-size: 10px;
}

.right {
  text-align: right;
  white-space: nowrap;
}

.scan {
  display: inline-block;
  padding: 4px 7px;
  border-radius: 999px;
  background: #eef2ff;
  color: #3730a3;
  font-size: 10px;
  font-weight: 900;
}

.scan.loaded,
.scan.received {
  background: #ecfdf5;
  color: #047857;
}

.scan.missing,
.scan.damaged,
.scan.cancelled {
  background: #fef2f2;
  color: #b91c1c;
}

.bottom-grid {
  display: grid;
  grid-template-columns: 1fr 330px;
  gap: 18px;
  margin-top: 18px;
  align-items: start;
}

.summary-box {
  padding: 0;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid #d0d5dd;
  font-size: 13px;
}

.summary-row:last-child {
  border-bottom: 0;
}

.note-box {
  min-height: 68px;
  font-size: 12px;
  color: #475467;
  line-height: 1.45;
}

.signatures {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 90px;
  margin-top: 56px;
}

.signature {
  border-top: 1px solid #101828;
  text-align: center;
  padding-top: 7px;
  font-size: 12px;
  font-weight: 700;
}

.footer {
  margin-top: 22px;
  padding-top: 10px;
  border-top: 1px solid #d0d5dd;
  color: #667085;
  font-size: 10px;
  text-align: center;
}

.empty {
  background: white;
  padding: 28px;
  text-align: center;
  color: #667085;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  .print-button {
    display: none;
  }
  .manifest {
    width: 210mm;
    min-height: 297mm;
    margin: 0;
    padding: 12mm;
    box-shadow: none;
  }
  .top-line {
    margin: -12mm -12mm 12mm;
  }
}

