  border: 1px solid #d0d5dd;
}

.items-head {
  display: flex;
  justify-content: space-between;
  background: #101828;
  color: white;
  padding: 11px 12px;
}

.items-head h2 {
  margin: 0;
  font-size: 15px;
}

.items-head span {
  color: #d0d5dd;
  font-size: 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  background: #f2f4f7;
  color: #344054;
  font-size: 11px;
  text-align: left;
  padding: 9px 8px;
  border-bottom: 1px solid #d0d5dd;
}

td {
  padding: 9px 8px;
  font-size: 12px;
  vertical-align: top;
  border-bottom: 1px solid #eaecf0;
}

tbody tr:nth-child(even) {
  background: #fbfcfd;
}

.product-code {
  font-weight: 900;
}

.product-name {
  margin-top: 2px;
  color: #667085;
  font-size: 11px;
}

small {
  display: block;
  margin-top: 2px;
  color: #667085;
  font-size: 10px;
}

.right {
  text-align: right;
  white-space: nowrap;
}

.scan {
  display: inline-block;
  padding: 4px 7px;
  border-radius: 999px;
  background: #eef2ff;
  color: #3730a3;
  font-size: 10px;
  font-weight: 900;
}

.scan.loaded,
.scan.received {
  background: #ecfdf5;
  color: #047857;
}

.scan.missing,
.scan.damaged,
.scan.cancelled {
  background: #fef2f2;
  color: #b91c1c;
}

.bottom-grid {
  display: grid;
  grid-template-columns: 1fr 330px;
  gap: 18px;
  margin-top: 18px;
  align-items: start;
}

.summary-box {
  padding: 0;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid #d0d5dd;
  font-size: 13px;
}

.summary-row:last-child {
  border-bottom: 0;
}

.note-box {
  min-height: 68px;
  font-size: 12px;
  color: #475467;
  line-height: 1.45;
}

.signatures {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 90px;
  margin-top: 56px;
}

.signature {
  border-top: 1px solid #101828;
  text-align: center;
  padding-top: 7px;
  font-size: 12px;
  font-weight: 700;
}

.footer {
  margin-top: 22px;
  padding-top: 10px;
  border-top: 1px solid #d0d5dd;
  color: #667085;
  font-size: 10px;
  text-align: center;
}

.empty {
  background: white;
  padding: 28px;
  text-align: center;
  color: #667085;
}

@media print {
  body {
    background: white;
  }

  .page {
    padding: 0;
  }

  .print-button {
    display: none;
  }

  .manifest {
    width: 210mm;
    min-height: 297mm;
    margin: 0;
    padding: 12mm;
    box-shadow: none;
  }

  .top-line {
    margin: -12mm -12mm 12mm;
  }
}
